classdef trial < handle
    % One trial. Every saved time is in ms since the trial start
    % (start_autogenerated) on the NIP clock; *_tick values are NIP ticks.
    % trialRecord builds the saved form (see documentation/timing.md).
    properties
        ttype

        start_tick        % NIP tick of the trial start: t = 0 of every *_ms time (tick = start_tick + 30*ms)
        start_clock       % date and time of the trial start (wall clock), to compare trials
        stop_ms           % end of the trial loop, ms after the start
        trialnum = 0;

        state             % per state: count, and per entry requested_ms / displayed_ms / photon_ms / delay_ms; code
        data
        targets           % per target: its settings, events, frames (what was shown) and computed (getpos)
        tags              % per mh.Screen 'Tag' name: events and frames
        success
        intervals

        trellis_trial_number;
        repeat = 0        % 0 = first attempt; 1, 2, ... = repeats of a failed trial
        repeat_of = []    % trialnum of the first attempt (its own trialnum for a first attempt)

        userdefined =[]

        System_Properties
        reward
    end

    methods
        function obj = insert(obj,field,varargin)
            for i = 1:length(varargin)
                try
                    if length(obj)==1
                        obj.(field).(varargin{i}.name)=varargin{i};
                    else
                        obj(end).(varargin{i}.name)=varargin{i};
                    end
                catch
                    obj.(field).other_data{i}=varargin{:};
                end
            end
        end


    end
end